/* 64-bit system call dispatch */

// C dependencies supplied by the surrounding kernel translation unit:
// linux/linkage.h, linux/sys.h, linux/cache.h, linux/syscalls.h,
// linux/entry-common.h, linux/nospec.h, asm/syscall.h

use core::ffi::c_long;

#[repr(C)]
pub struct pt_regs {
    pub ax: u64,
    pub cx: u64,
    pub ip: u64,
    pub r11: u64,
    pub flags: u64,
    pub cs: u64,
    pub ss: u64,
}

pub type sys_call_ptr_t = unsafe extern "C" fn(*const pt_regs) -> c_long;

// The following declarations are generated by asm/syscalls_64.h and, when
// enabled, asm/syscalls_x32.h.  Their exact contents are supplied externally.
extern "C" {
    fn __x64_sys_ni_syscall(regs: *const pt_regs) -> c_long;
    fn syscall_enter_from_user_mode_randomize_stack(regs: *mut pt_regs, nr: *mut c_long) -> bool;
    fn instrumentation_begin();
    fn instrumentation_end();
    fn syscall_exit_to_user_mode(regs: *mut pt_regs);
    fn cpu_feature_enabled(feature: u32) -> bool;
    fn array_index_nospec(nr: usize, size: usize) -> usize;
}

// The C preprocessor expands this table from asm/syscalls_64.h.  The include
// is intentionally not reproduced as executable Rust; the generated entries
// are an external dependency of this isolated translation.
pub static sys_call_table: &[sys_call_ptr_t] = &[];

// The unsigned int @nr argument is intentional as it creates denser code.
#[inline(never)]
unsafe fn x64_sys_call(regs: *const pt_regs, nr: u32) -> c_long {
    // asm/syscalls_64.h expands to `case nr: return __x64_<symbol>(regs);`.
    // The generated match arms are supplied by that external header.
    let _ = nr;
    __x64_sys_ni_syscall(regs)
}

#[inline(never)]
unsafe fn x32_sys_call(regs: *const pt_regs, nr: u32) -> c_long {
    // CONFIG_X86_X32_ABI / asm/syscalls_x32.h provide the generated match.
    #[cfg(CONFIG_X86_X32_ABI)]
    {
        let _ = nr;
        return __x64_sys_ni_syscall(regs);
    }
    #[cfg(not(CONFIG_X86_X32_ABI))]
    {
        let _ = (regs, nr);
        return -38; // -ENOSYS
    }
}

#[inline(always)]
unsafe fn do_syscall_x64(regs: *mut pt_regs, mut nr: usize) -> bool {
    if nr < NR_SYSCALLS {
        nr = array_index_nospec(nr, NR_SYSCALLS);
        (*regs).ax = x64_sys_call(regs, nr as u32) as u64;
        return true;
    }
    false
}

#[inline(always)]
unsafe fn do_syscall_x32(regs: *mut pt_regs, mut nr: usize) {
    /* Adjust the starting offset of the table */
    nr = nr.wrapping_sub(X32_SYSCALL_BIT);

    if cfg!(CONFIG_X86_X32_ABI) && nr < X32_NR_SYSCALLS {
        nr = array_index_nospec(nr, X32_NR_SYSCALLS);
        (*regs).ax = x32_sys_call(regs, nr as u32) as u64;
    }
}

// Returns true to return using SYSRET, or false to use IRET.
#[no_mangle]
pub unsafe extern "C" fn do_syscall_64(regs: *mut pt_regs, mut nr: c_long) -> bool {
    if syscall_enter_from_user_mode_randomize_stack(regs, &mut nr) {
        instrumentation_begin();

        if !do_syscall_x64(regs, nr as usize) {
            do_syscall_x32(regs, nr as usize);
        }

        instrumentation_end();
    }
    syscall_exit_to_user_mode(regs);

    /*
     * Check that the register state is valid for using SYSRET to exit
     * to userspace.  Otherwise use the slower but fully capable IRET
     * exit path.
     */

    /* XEN PV guests always use the IRET path */
    if cpu_feature_enabled(X86_FEATURE_XENPV) {
        return false;
    }

    /* SYSRET requires RCX == RIP and R11 == EFLAGS */
    if (*regs).cx != (*regs).ip || (*regs).r11 != (*regs).flags {
        return false;
    }

    /* CS and SS must match the values set in MSR_STAR */
    if (*regs).cs != USER_CS || (*regs).ss != USER_DS {
        return false;
    }

    /*
     * On Intel CPUs, SYSRET with non-canonical RCX/RIP will #GP
     * in kernel space.  This essentially lets the user take over the
     * kernel, since userspace controls RSP.
     *
     * TASK_SIZE_MAX covers all user-accessible addresses other than
     * the deprecated vsyscall page.
     */
    if (*regs).ip >= TASK_SIZE_MAX {
        return false;
    }

    /* SYSRET cannot restore RF.  It can restore TF, but unlike IRET,
     * restoring TF results in a trap from userspace immediately after
     * SYSRET.
     */
    if ((*regs).flags & (X86_EFLAGS_RF | X86_EFLAGS_TF)) != 0 {
        return false;
    }

    /* Use SYSRET to exit to userspace */
    true
}

// Constants and generated syscall declarations are supplied by the external
// kernel headers referenced above.
extern "Rust" {
    static NR_SYSCALLS: usize;
    static X32_NR_SYSCALLS: usize;
    static X32_SYSCALL_BIT: usize;
    static X86_FEATURE_XENPV: u32;
    static USER_CS: u64;
    static USER_DS: u64;
    static TASK_SIZE_MAX: u64;
    static X86_EFLAGS_RF: u64;
    static X86_EFLAGS_TF: u64;
}

